import Foundation

enum RoachBlueNoise {
    static let side = 64
    static let base64 =
        ""

    static let bytes: [UInt8] = {
        guard let data = Data(base64Encoded: base64), data.count == side * side else {
            return [UInt8](repeating: 128, count: side * side)
        }
        return [UInt8](data)
    }()
}
